#!/usr/bin/env bash
# DOC DEV : réorganisation du menu latéral.
#   - sections = les parties du parcours (Démarrer, Fondations front, Données, API,
#     Authentification et droits, Stockage et médias, Domaine du club, Interface transverse…) ;
#   - les 6 grands tutos et le chapitre « domaine » rangés dans leur partie, titrés en français,
#     avec un avertissement « chapitre hérité » en tête ;
#   - supprimés (redondants ou ébauches) : introduction/*, architecture/* (8), domain-model,
#     patterns/hooks, roadmap, tutorials-overview ; la pile technique passe dans « Avant de commencer » ;
#   - accueil de l'espace dev : tableau des parties et de leur état ;
#   - extraits de code : un fichier disparu affiche un avertissement au lieu d'une erreur 500
#     (corrige la page tRPC) ; DocsTable n'est plus paginé.
# Prérequis : apply-docs-sobre-pastel.sh.
# Usage (racine du repo) : bash apply-docs-reorg.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/src/features/docs/lib/docs.navigation.ts" 2>/dev/null | grep -qF "\"Étude de cas\""; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "Tons pastel" "apps/web/src/features/docs/ui/Callout.tsx" 2>/dev/null || { echo "❌ lancer d'abord apply-docs-sobre-pastel.sh"; exit 1; }
MODIFIED=("apps/web/src/app/docs/[...slug]/page.tsx" "apps/web/src/features/docs/lib/code.utils.ts" "apps/web/src/features/docs/lib/docs.navigation.ts" "apps/web/src/features/docs/ui/DocsTable.tsx" "apps/web/content/docs/dev/demarrer/avant-de-commencer.mdx" "apps/web/content/docs/dev/index.mdx")
CREATED=("apps/web/content/docs/dev/api/trpc.mdx" "apps/web/content/docs/dev/auth/authentification.mdx" "apps/web/content/docs/dev/domaine/comprendre-le-domaine.mdx" "apps/web/content/docs/dev/donnees/modeliser-avec-prisma.mdx" "apps/web/content/docs/dev/interface/formulaires.mdx" "apps/web/content/docs/dev/stockage/le-finder.mdx" "apps/web/content/docs/dev/stockage/signer-un-upload.mdx")
restore(){ [ -n "${DELETED+x}" ] && { git reset -q -- "${DELETED[@]}" 2>/dev/null; git checkout -q -- "${DELETED[@]}" 2>/dev/null; }; git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "\"Étude de cas\"" "apps/web/src/features/docs/lib/docs.navigation.ts" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
trap 'restore' ERR

mkdir -p "apps/web/content/docs/dev/demarrer"
base64 -d > "apps/web/content/docs/dev/demarrer/avant-de-commencer.mdx" <<'B64'
