DELETED=("apps/web/content/docs/dev/architecture/architecture-map.mdx" "apps/web/content/docs/dev/architecture/authentication-architecture.mdx" "apps/web/content/docs/dev/architecture/backend-architecture.mdx" "apps/web/content/docs/dev/architecture/cloudinary-finder-architecture.mdx" "apps/web/content/docs/dev/architecture/frontend-architecture.mdx" "apps/web/content/docs/dev/architecture/mobile-readiness.mdx" "apps/web/content/docs/dev/architecture/project-architecture.mdx" "apps/web/content/docs/dev/architecture/technology-stack.mdx" "apps/web/content/docs/dev/domain/domain-model.mdx" "apps/web/content/docs/dev/domain/domain.mdx" "apps/web/content/docs/dev/introduction/learning-roadmap.mdx" "apps/web/content/docs/dev/introduction/project-overview.mdx" "apps/web/content/docs/dev/patterns/hooks.mdx" "apps/web/content/docs/dev/roadmap.mdx" "apps/web/content/docs/dev/tutorials/authentication-with-trpc.mdx" "apps/web/content/docs/dev/tutorials/forms-with-useform-useactionstate.mdx" "apps/web/content/docs/dev/tutorials/le-finder-cloudinary.mdx" "apps/web/content/docs/dev/tutorials/modelise-data-with-prisma.mdx" "apps/web/content/docs/dev/tutorials/signer-et-persister-un-upload-cloudinary.mdx" "apps/web/content/docs/dev/tutorials/trpc_backend.mdx" "apps/web/content/docs/dev/tutorials/tutorials-overview.mdx")
# Une page à supprimer modifiée localement est d'abord mise de côté (jamais perdue).
BK="_docs_supprimees_$(date +%Y%m%d-%H%M%S)"
for f in "${DELETED[@]}"; do
  if [ -f "$f" ] && ! git diff --quiet HEAD -- "$f" 2>/dev/null; then
    mkdir -p "$BK/$(dirname "$f")"; cp "$f" "$BK/$f"; echo "  ⚠ $f modifié localement → copie dans $BK/"
  fi
done
git rm -qf --ignore-unmatch -- "${DELETED[@]}"
echo "  21 pages supprimées"
[ "${AKFC_APPLY_ONLY:-0}" = "1" ] && { echo "Appliqué (sans vérification ni commit)."; exit 0; }
echo "== pnpm check =="
if pgrep -f "next dev" >/dev/null 2>&1; then
  echo "  (pnpm dev tourne : vérification sans effacer .next)"
  CHECK="node scripts/check-next-conventions.mjs && node scripts/check-tour-targets.mjs && pnpm --filter backend typecheck && pnpm typecheck"
else
  CHECK="pnpm check"
fi
if ! bash -c "$CHECK" > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"
  grep -nE "error TS|✗ tutos|ERR_|Error:|EACCES|Permission denied" /tmp/akfc_tc.log | head -12
  echo "  … fin du journal :"; grep -v '^[[:space:]]*$' /tmp/akfc_tc.log | tail -15
  restore; exit 1
fi
echo "  ✅ check OK"
git add "${MODIFIED[@]}" "${CREATED[@]}"
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
docs(dev): menu latéral réorganisé selon les parties du parcours

- Sections alignées sur les parties (Démarrer → Étude de cas).
- Tutos existants rangés dans leur partie, titres en français,
  avertissement « chapitre hérité » en tête.
- Pages redondantes ou ébauches supprimées (introduction, architecture,
  domain-model, hooks, roadmap, tutorials-overview).
- Pile technique intégrée à « Avant de commencer » ; accueil dev =
  tableau des parties.
- CodeExample : fichier introuvable → avertissement (plus de 500) ;
  DocsTable affiché en entier.

